import { unzipSync } from "fflate";
// Generates the Mekanism sprite registry + CSS from one pinned upstream commit.
// Run: pnpm --filter @verdigris/textures sync:mekanism-sprites
//
// The commit is pinned so the generated files are reproducible. `--check`
// re-renders and compares against the committed files.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const COMMIT = "d4df9b354c209c85713bdc8a017bfe54aa044e40";
const ZIP_URL = `https://codeload.github.com/mekanism/Mekanism/zip/${COMMIT}`;
const ASSET_ROOT = "src/main/resources/assets/mekanism/textures/";
const EXTRA_ROOTS = [
  `${ASSET_ROOT}item/upgrade/`,
  `${ASSET_ROOT}mek_liquid/`,
  `${ASSET_ROOT}mek_chemical/`,
];

const ROOT = fileURLToPath(new URL("../", import.meta.url));
const OUT_TS = `${ROOT}src/mekanism-sprites.generated.ts`;
const OUT_CSS = `${ROOT}css/mekanism-sprites.generated.css`;
const OUT_TEXTURES = `${ROOT}css/mekanism-textures.css`;

const check = process.argv.includes("--check");

function cssVar(name) {
  return `--mc-mek-${name.toLowerCase().replaceAll(/[^a-z0-9]+/g, "-")}`;
}

async function download(url) {
  let lastError;
  for (let attempt = 1; attempt <= 4; attempt += 1) {
    try {
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status} ${response.statusText}`);
      }
      return new Uint8Array(await response.arrayBuffer());
    }
    catch (error) {
      lastError = error;
      if (attempt < 4) {
        await new Promise(resolve => setTimeout(resolve, attempt * 500));
      }
    }
  }
  throw new Error(`cannot download ${url}`, { cause: lastError });
}

function parseScaling(mcmeta) {
  if (!mcmeta) {
    return null;
  }
  try {
    const scaling = JSON.parse(mcmeta).gui?.scaling;
    if (scaling?.type === "nine_slice") {
      return {
        border: scaling.border,
        height: scaling.height,
        type: "nine_slice",
        width: scaling.width,
      };
    }
    return scaling?.type === "tile"
      ? { height: scaling.height, type: "tile", width: scaling.width }
      : null;
  }
  catch {
    return null;
  }
}

function pngSize(bytes) {
  const view = new DataView(bytes.buffer, bytes.byteOffset);
  return { height: view.getUint32(20), width: view.getUint32(16) };
}

function sourceName(fullName) {
  const marker = fullName.indexOf(ASSET_ROOT);
  if (marker === -1) {
    return null;
  }
  const assetName = fullName.slice(marker);
  const relative = assetName.slice(ASSET_ROOT.length);
  if (relative.startsWith("gui/sprites/")) {
    return relative.slice("gui/sprites/".length, -".png".length);
  }
  return EXTRA_ROOTS.some(root => assetName.startsWith(root))
    ? relative.slice(0, -".png".length)
    : null;
}

const zip = await download(ZIP_URL);
const files = unzipSync(zip, {
  filter(file) {
    const name = file.name;
    return Boolean(name.includes(ASSET_ROOT)) && Boolean(name.endsWith(".png") || name.endsWith(".png.mcmeta")) && (sourceName(name) !== null);
  },
});

const sprites = new Map();
for (const [fullName, bytes] of Object.entries(files)) {
  if (!fullName.endsWith(".png")) {
    continue;
  }
  const name = sourceName(fullName);
  if (name === null) {
    continue;
  }
  const mcmetaBytes = files[`${fullName}.mcmeta`];
  const mcmeta = mcmetaBytes ? new TextDecoder().decode(mcmetaBytes) : null;
  sprites.set(name, { bytes, scaling: parseScaling(mcmeta) });
}

const entries = sprites.entries()
  .map(([name, { bytes, scaling }]) => {
    const { height, width } = pngSize(bytes);
    return {
      base64: Buffer.from(bytes).toString("base64"),
      cssVar: cssVar(name),
      height,
      name,
      scaling,
      sha256: createHash("sha256").update(bytes).digest("hex"),
      width,
    };
  })
  .toArray()
  .toSorted((a, b) => a.name.localeCompare(b.name));

if (entries.length < 280) {
  throw new Error(`expected at least 280 Mekanism sprites, got ${entries.length}`);
}

function scalingLiteral(scaling) {
  return scaling === null
    ? "null"
    : `{ ${Object.entries(scaling).map(([key, value]) => `${key}: ${JSON.stringify(value)}`).join(", ")} }`;
}

const metaLines = entries.map(entry => `  ${/^[a-z][\w$]*$/i.test(entry.name) ? entry.name : JSON.stringify(entry.name)}: {
    cssVar: ${JSON.stringify(entry.cssVar)},
    height: ${entry.height},
    scaling: ${scalingLiteral(entry.scaling)},
    sha256: ${JSON.stringify(entry.sha256)},
    width: ${entry.width},
  },`);

const ts = `// Generated by scripts/sync-mekanism-sprites.mjs — DO NOT EDIT.
// Source: Mekanism ${COMMIT} (MIT, Copyright (c) 2017-2025 Aidan C. Brady).
// See LICENSE-ASSETS.md.
// Regenerate: pnpm --filter @verdigris/textures sync:mekanism-sprites

export type MekanismSpriteScaling =
  | null
  | { border: number; height: number; type: "nine_slice"; width: number }
  | { height: number; type: "tile"; width: number };

export interface MekanismSpriteMeta {
  cssVar: string;
  height: number;
  scaling: MekanismSpriteScaling;
  sha256: string;
  width: number;
}

export const mekanismSpriteMeta = {
${metaLines.join("\n")}
} as const;

export type MekanismSpriteName = keyof typeof mekanismSpriteMeta;
`;

const cssLines = entries.map(
  entry => `  ${entry.cssVar}: url("data:image/png;base64,${entry.base64}");`,
);

const css = `/*
 * Generated by scripts/sync-mekanism-sprites.mjs — DO NOT EDIT.
 * Source: Mekanism ${COMMIT} (MIT, Copyright (c) 2017-2025 Aidan C. Brady).
 * See LICENSE-ASSETS.md.
 */
:root {
${cssLines.join("\n")}
}
`;

const textures = `/*
 * Mekanism sprite layer. Import after the vanilla sprite CSS.
 * Generated data URIs live in mekanism-sprites.generated.css.
 */
@import "./mekanism-sprites.generated.css";

.mc-mek-sprite {
  background-repeat: no-repeat;
  image-rendering: pixelated;
}
`;

if (check) {
  let isStale = false;
  for (const [file, expected] of [
    [OUT_TS, ts],
    [OUT_CSS, css],
    [OUT_TEXTURES, textures],
  ]) {
    let actual = "";
    try {
      actual = readFileSync(file, "utf8");
    }
    catch {
      isStale = true;
      continue;
    }
    if (actual === expected) {
      continue;
    }
    isStale = true;
    console.error(`out of date: ${file}`);
  }
  if (isStale) {
    process.exit(1);
  }
  console.log(`Mekanism sprites up to date (${entries.length})`);
}
else {
  writeFileSync(OUT_TS, ts);
  writeFileSync(OUT_CSS, css);
  writeFileSync(OUT_TEXTURES, textures);
  console.log(`wrote ${entries.length} Mekanism sprites`);
}
